// Mirrors order-import.js CATEGORIES; the almirah shelves all ten.
const CATEGORIES=['Shirts','Trousers','Ethnic wear','Footwear','Accessories','Belts','Dresses','Suits','Outerwear','Jewellery'];
const icons={developer:'<path d="M4 20h16M6 16V9m6 7V4m6 12v-5"/>',discover:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',wardrobe:'<path d="M10 5a2 2 0 1 1 3 1.7L12 8v2L3 16v2h18v-2l-9-6"/>',style:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',insights:'<path d="M4 20V12m8 8V4m8 16v-7"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4Z"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1"/><path d="m3 17 5-5 4 4 3-6 6 8"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a17 17 0 0 0 0 18 17 17 0 0 0 0-18"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.1"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',undo:'<path d="M4 4v6h6M4 10a8 8 0 1 1 0 8"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14Z"/>',sliders:'<path d="M4 7h16M4 17h16M8 4v6M16 14v6"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.style}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(v);
const catalog=[
{id:'denim',name:'Relaxed blue denim',category:'Trousers',image:'assets/denim.jpg',price:2299,description:'A blue-denim alternative to the black trousers. Image and price are illustrative.',tags:['Blue','Denim','Relaxed'],retailer:'Sample denim store'},
{id:'cream',name:'Cream camp-collar shirt',category:'Shirts',image:'assets/cream.png',price:2499,description:'A relaxed silhouette and warm cream tone. A camp collar keeps it easy.',tags:['Cream','Relaxed fit','Camp collar'],retailer:'Sample retailer'},
{id:'black',name:'Black chinos',category:'Trousers',image:'assets/trousers.png',price:2999,description:'A clean, tapered shape with a deep black finish.',tags:['Black','Tapered','Everyday'],retailer:'Sample marketplace'},
{id:'tee',name:'White everyday T-shirt',category:'Shirts',image:'assets/tee.jpg',price:999,description:'An easy white crew neck to anchor a casual look.',tags:['White','Crew neck','Short sleeve'],retailer:'Sample retailer'},
{id:'glasses',name:'Matte black sunglasses',category:'Accessories',image:'assets/sunglasses.jpg',price:1599,description:'A rounded frame and matte finish for a quiet statement.',tags:['Black','Rounded frame'],retailer:'Sample accessories store'},
{id:'shoes',name:'White low-top sneakers',category:'Footwear',image:'assets/sneaker.jpg',price:3499,description:'Clean white sneakers with a low profile.',tags:['White','Low top'],retailer:'Sample footwear store'},
{id:'belt',name:'Brown leather belt',category:'Belts',image:'assets/belt.jpg',price:1299,description:'A simple brown belt to tie the outfit together.',tags:['Brown','Leather look'],retailer:'Sample retailer'}];
const product=id=>catalog.find(p=>p.id===id)||state.external?.find(p=>p.id===id);
const seed=()=>({items:['black','tee','glasses','shoes','belt'].map((id,i)=>({...product(id),owned:true,source:'Sample wardrobe',price:i===4?null:product(id).price,purchased:'2026-02-14',reviews:id==='black'?[{date:'2026-08-14',text:'After six months, the button came loose. The fabric still feels good.',rating:4}]:[]})),saved:[],looks:[],mode:'Frugal maxing',metrics:['cpw','variety','spend','wears'],milestoneDismissed:false,wears:Array.from({length:20},(_,i)=>({id:'seed-'+i,date:`2026-08-${String(i+1).padStart(2,'0')}`,items:['black',...(i%6===0?['tee','glasses']:i%6===1?['tee','shoes']:i%6===2?['glasses','shoes']:i%6===3?['tee','belt']:i%6===4?['shoes','belt']:['tee','glasses','shoes'])],occasion:i<9?'Work':i<15?'Evening':i<18?'Travel':'Untagged'})),shops:[],aiConsent:false,v:2});
// New people start with an empty almirah (PRD FR#1): the five sample pieces only come back from
// "Reset sample data". Earlier visitors lose the untouched sample pieces once; their own stay.
const emptyState=()=>({items:[],saved:[],looks:[],mode:'Frugal maxing',metrics:['cpw','variety','spend','wears'],milestoneDismissed:false,wears:[],shops:[],aiConsent:false,syncs:{},v:2});
function migrate(s){if(!s.v){s.items=s.items.filter(p=>p.source!=='Sample wardrobe');s.wears=s.wears.filter(w=>!String(w.id).startsWith('seed-'));s.v=2;}s.shops??=[];s.syncs??={};s.saved??=[];s.looks??=[];return s;}
let state=emptyState();try{const saved=JSON.parse(localStorage.getItem('tbw-atelier-v1'));if(saved?.items&&saved?.wears)state=migrate(saved);}catch{}
let storageWarning=false;
const persist=()=>{window.WardrobeSync?.push(state);try{localStorage.setItem('tbw-atelier-v1',JSON.stringify(state));storageWarning=false;return true;}catch{storageWarning=true;return false;}};
const item=id=>state.items.find(i=>i.id===id)||product(id);
let assemblyMode='exploded',wardrobeOpening=false;
let route=location.hash.slice(1)||'discover',category='All',shelf='owned',query='',ref={image:'assets/outfit.png',sample:true,label:'Cream shirt & black chinos'},target='Shirt',importDraft=[],uploadPurpose='discover',styleIds=['cream','black','shoes'],kept=[],previous=null,styleOccasion='Travel',styleTitle='Kerala trip · beach evening',styleMessage='A cream shirt, clean black chinos, and your white sneakers. Easy contrast for an evening out.',personalPhoto=null,insightItem='black',toastTimer,scrolls={},lastFocus;
const main=document.querySelector('main'),dialog=document.querySelector('dialog'),fileInput=document.querySelector('#photo-input');
// Funnel order: discover what you want, fill your wardrobe, then style it.
const tabs=[['discover','Discover'],['wardrobe','My Wardrobe'],['style','Style Me'],['profile','My Profile']];
// Modules not ready for testers yet (owner, 6 Oct 2026): shown blurred behind a "Coming soon" card.
// To re-enable one, remove it from this set.
const COMING_SOON=new Set(['style']);
const SOON_COPY={wardrobe:['My Wardrobe','Your clothes, on a real almirah: add what you own, see what you wear, and get more out of every piece.'],style:['Style Me','Outfit ideas from your own wardrobe and new finds, styled around you by AI.']};
function comingSoon(id,preview){const [name,line]=SOON_COPY[id];return `<div class="soon-wrap"><div class="soon-preview" aria-hidden="true" inert>${preview}</div><div class="soon-card" role="status"><span class="soon-badge">Coming soon</span><h1>${name} is on its way</h1><p>${line}</p><p class="soon-note">For now, start with Discover: find any look, from a screenshot or a few words.</p><a class="btn" href="#discover">${icon('discover')} Go to Discover</a></div></div>`;}
let developerEnabled=false,capabilitiesLoaded=false;
function toast(msg){clearTimeout(toastTimer);const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');toastTimer=setTimeout(()=>t.classList.remove('show'),3500);}
function go(next){if(next===route){render();return;}location.hash=next;}
function nav(){const active=route.split('/')[0];const link=([id,name])=>`<a href="#${id}" class="nav-link ${active===id?'active':''} ${COMING_SOON.has(id)?'soon':''}" ${active===id?'aria-current="page"':''}>${icon(id)}${name}${COMING_SOON.has(id)?'<em class="soon-tag">Soon</em>':''}${id==='wardrobe'&&pendingCount()?`<em class="tab-badge" aria-label="${pendingCount()} pieces to review">${pendingCount()}</em>`:''}</a>`;const core=tabs.map(link).join('');
 document.querySelector('#desktop-nav').innerHTML=developerEnabled?core+link(['developer','Developer']):core;
 document.querySelector('#bottom-nav').innerHTML=core;
 const devLink=document.querySelector('#developer-link');if(devLink){devLink.innerHTML=icon('developer');devLink.classList.toggle('enabled',developerEnabled);devLink.classList.toggle('active',active==='developer');}
}
function modal(title,body,actions=''){lastFocus=document.activeElement;document.querySelector('#dialog-content').innerHTML=`<div class="modal"><div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}${actions?`<div class="modal-actions">${actions}</div>`:''}</div>`;if(!dialog.open)dialog.showModal();}
function close(){dialog.close();if(lastFocus?.isConnected)lastFocus.focus();}
function img(p,extra=''){return `<div class="well ${extra}"><img src="${esc(p.image)}" alt="${esc(p.name||p.label)}" loading="lazy"></div>`;}
function notice(text='Sample data · saved on this device only'){return `<div class="preview-notice">${icon('info')} ${text}${storageWarning?' · Storage full: new changes last for this session only.':''}</div>`;}
function heading(title,desc='',action=''){return `<div class="page-head"><div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`;}
function chip(label,action,value,active=false){return `<button class="chip ${active?'active':''}" data-action="${action}" data-value="${esc(value)}" aria-pressed="${active}">${esc(label)}</button>`;}
function discover(){return `<div class="eyebrow">The after-hours atelier</div>${heading('Find your <em>next</em> look.','',`<span class="pill">${icon('globe')} India first. Inspiration everywhere.</span>`)}<div class="entry-grid"><div><div class="upload-zone" id="drop-zone"><div class="upload-illustration"><img src="assets/cream.png" alt="Cream shirt example">${icon('plus')}</div><h2>Drop a screenshot. Find the vibe.</h2><p>Any app, any film still, any saved photo. We chase the vibe — never a promise of the exact piece.</p><button class="btn" data-action="upload-discover">${icon('upload')} Upload screenshot</button><span class="note">JPG, PNG or WebP · up to 10 MB</span></div><div class="entry-foot"><span class="note">Photos stay local until you start AI analysis or search.</span><button class="link-btn" data-action="sample" data-value="Shirt">Try an example ${icon('arrow')}</button></div><div class="future-input"><div class="row between"><span class="small">Have a link or a look in mind?</span><span class="pill">Later release</span></div><p class="note">Image-first for now. Link and natural-language discovery are next.</p></div></div><div><div class="section-head start"><h2>Start from a reference</h2><button class="link-btn" data-action="references">See all</button></div><div class="collections">${[['cream','Draper-coded','Shirt'],['denim','Oversized denim','Trousers'],['glasses','The finishing touch','Accessories']].map(([id,name,t])=>`<button class="collection" data-action="sample" data-value="${t}">${img(product(id))}<h3>${name}</h3></button>`).join('')}</div><div class="editorial-note"><span class="mini-ribbon ribbon" aria-hidden="true"></span><h2>Good taste.<br><em>Your own take.</em></h2><p>Find the pieces. Remix what you own.<br>Make a little room for the unexpected.</p><div class="tiny-rule"></div><span class="eyebrow">A wardrobe, connected.</span></div></div></div><div class="note-box">${notice('Upload your own screenshot for live discovery. Reference collections remain illustrative examples.')}</div>`;}
function selection(){if(!ref.sample&&window.Discovery)return window.Discovery.selection(ref);const targetProduct=product(target==='Trousers'?'black':target==='Accessories'?'glasses':'cream');return `<div class="toolbar"><button class="link-btn" data-action="go" data-value="discover">${icon('back')} Back</button><button class="link-btn" data-action="upload-discover">Replace image</button></div>${heading('Which piece are we <em>chasing?</em>','Choose a garment, or search the whole look.')}<div class="selection-layout"><div class="panel reference-panel"><img class="reference-photo" src="${esc(ref.image)}" alt="${esc(ref.label)}">${ref.sample?`<button class="target-box target-shirt ${target==='Shirt'?'chosen':''}" data-action="target" data-value="Shirt" aria-label="Select shirt in sample reference"><span>Shirt</span></button><button class="target-box target-trousers ${target==='Trousers'?'chosen':''}" data-action="target" data-value="Trousers" aria-label="Select trousers in sample reference"><span>Trousers</span></button>`:''}<span class="reference-caption">${ref.sample?'Sample reference':'Your uploaded reference'}</span></div><div class="stack"><div class="chip-row">${['Shirt','Trousers','Accessories','Whole look'].map(t=>chip(t,'target',t,target===t)).join('')}</div><div class="panel row">${img(targetProduct,'thumb')}<div><strong>${ref.sample?esc(targetProduct.name):esc(target)+' selected'}</strong><p class="note">${ref.sample?'Example search target':'Selected by you · no image recognition yet'}</p></div></div><div><h3>${ref.sample?'Reference details':'Describe what matters'}</h3><div class="chip-row spaced">${(ref.sample?targetProduct.tags:['Colour','Shape','Overall vibe']).map(t=>`<span class="pill">${esc(t)}</span>`).join('')}<span class="pill warn">Fabric — not verified</span></div></div><label class="field">Optional detail<input id="target-detail" placeholder="e.g. keep the relaxed fit" maxlength="160"></label><div class="panel raised"><p class="note">${ref.sample?'This example shows the intended selection flow.':'Your image is displayed locally. Select the target manually for this walkthrough.'} The next screen contains sample matches, not live search results.</p></div><button class="btn full" data-action="matches">View sample matches ${icon('arrow')}</button></div></div>`;}
function resultCard(p,global=false){const saved=state.saved.includes(p.id),owned=state.items.some(i=>i.id===p.id);return `<article class="result-card"><button class="result-image" data-action="product" data-id="${p.id}" aria-label="View ${esc(p.name)}">${img(p)}</button><div class="result-content"><div class="row between"><button class="product-name" data-action="product" data-id="${p.id}">${esc(p.name)}</button><button class="icon-btn save-btn ${saved?'saved':''}" data-action="save" data-id="${p.id}" aria-label="${saved?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${saved}">${icon(saved?'check':'bookmark')}</button></div><p class="note">${global?'Sample store (US) · $68':esc(p.retailer)+' · '+money(p.price)}</p><div class="chip-row"><span class="pill rose">Similar style · demo</span><span class="pill warn">${global?'India delivery unknown':'Availability not checked'}</span>${owned?'<span class="pill green">In your wardrobe</span>':''}</div><p class="match-copy">${esc(p.description)}</p><div class="row"><button class="link-btn" data-action="product" data-id="${p.id}">View piece ${icon('arrow')}</button><button class="link-btn" data-action="style-item" data-id="${p.id}">Style it</button></div></div></article>`;}
function results(){if(!ref.sample&&window.Discovery)return window.Discovery.results();const list=target==='Trousers'?[product('black'),product('denim')]:target==='Accessories'?[product('glasses'),product('belt')]:target==='Whole look'?[product('cream'),product('black'),product('glasses')]:[product('cream'),product('tee')];return `<div class="reference-strip"><img src="${esc(ref.image)}" alt="Reference thumbnail"><div><strong>${esc(target==='Whole look'?'The complete look':target+' inspiration')}</strong><p class="note">Searching the vibe, not the exact piece</p></div><button class="link-btn" data-action="go" data-value="discover/select">Change</button></div>${notice('Demonstration catalog · example prices · no live matching or stock verification.')}<div class="results-layout"><div><div class="section-head start"><h2>India shopping options <span class="count">${list.length}</span></h2><span class="pill">India</span></div><div class="stack">${list.map(p=>resultCard(p)).join('')}</div></div><aside><div class="section-head start"><h2>Global matches</h2>${icon('globe')}</div>${resultCard(product(target==='Trousers'?'black':target==='Accessories'?'glasses':'cream'),true)}<div class="note-box note">Exact-item identification is not connected. These examples show how similar pieces and delivery information will be presented.</div><button class="link-btn" data-action="go" data-value="discover/select">Try another target ${icon('arrow')}</button></aside></div>`;}
function wardrobeLevel(count){const levels=[[100,5,'Tastemaker'],[60,4,'Archivist'],[30,3,'Curator'],[15,2,'Stylist'],[0,1,'Collector']];const x=levels.find(([n])=>count>=n);return {number:x[1],title:x[2]};}
// Real progress (PRD FR#16): XP, level and streak from the pieces and wears actually recorded.
function stats(){const W=window.WardrobeIntake;if(W)return W.progress(state);const l=wardrobeLevel(state.items.length);return {xp:0,number:l.number,title:l.title,nextAt:null,streak:0,pieces:state.items.length};}
const pendingCount=()=>importDraft.filter(p=>!p.hidden).length;
// Pieces waiting in the review queue, wherever the person is in My Wardrobe.
function reviewBanner(){const n=pendingCount();if(!n||route==='wardrobe/import')return '';const busy=jobs.some(j=>!j.done);return `<button class="review-banner" data-action="go" data-value="wardrobe/import"><span><strong>${n} ${n===1?'piece':'pieces'} to review</strong><small>${busy?'Still finding more…':'Tick what is yours, then save.'}</small></span><b>Review →</b></button>`;}
// Guests keep everything on this device; one quiet line offers sign-in once there is something to lose.
function syncNote(){const a=window.TBWAccount;if(!state.items.length||!a||a.signedIn||!a.google)return '';return `<p class="sync-note">Saved on this device only. <a href="#welcome">Sign in with Google</a> to keep your wardrobe on every device.</p>`;}
function wardrobeAdd(){const n=Math.min(state.items.length,5),left=Math.max(0,5-n),unlocked=n>=5;return `<div class="wardrobe-screen wardrobe-add"><div class="wardrobe-head"><h1>My Wardrobe</h1>${state.items.length?'<button data-action="wardrobe-skip">Skip</button>':''}</div>${reviewBanner()}<div class="unlock-card"><div><strong>Level 1 · Collector</strong><span>${n} / 5 pieces</span></div><div class="unlock-track"><i style="width:${n/5*100}%"></i></div><p>${unlocked?'Your wardrobe is unlocked.':`Add ${left} more ${left===1?'piece':'pieces'} and your wardrobe doors unlock.`}</p></div>${importHub()}${syncNote()}<div class="wardrobe-dock"><button class="wardrobe-primary" data-action="${unlocked?'wardrobe-open':'import-camera'}">${unlocked?'Open wardrobe':'Open camera →'}</button></div></div>`;}
function wardrobeClosed(){const n=state.items.length,s=stats(),idle=window.WardrobeIntake?.notWornSince(state,60)||0;if(!n)return `<div class="wardrobe-screen">${heading('Your wardrobe','Empty for now')}${reviewBanner()}<div class="almirah closed empty"><div class="doors"><button class="door left" data-action="add-photos" aria-label="Add your first piece"><i></i></button><span class="seam"></span><button class="door right" data-action="add-photos" aria-label="Add your first piece"><i></i></button><span class="count-plate">Empty for now</span></div></div><div class="wardrobe-dock"><button class="wardrobe-primary" data-action="add-photos">Add your first piece →</button></div></div>`;return `<div class="wardrobe-screen"><div class="status-pills"><span>Level ${s.number} · ${s.title}</span><span>${s.streak?`${s.streak}-day streak`:'No streak yet'}</span><span>${s.xp} XP</span></div><div class="wardrobe-title"><h1>Your wardrobe</h1><p>${n} ${n===1?'piece':'pieces'}${idle?` · ${idle} not worn in 60 days`:''}${s.nextAt?` · ${s.nextAt-n} to the next level`:''}</p></div>${reviewBanner()}<div class="almirah closed ${wardrobeOpening?'opening':''}"><div class="almirah-interior-preview"></div><div class="doors"><button class="door left" data-action="wardrobe-open" aria-label="Open wardrobe"><i></i></button><span class="seam"></span><button class="door right" data-action="wardrobe-open" aria-label="Open wardrobe"><i></i></button><button class="count-plate" data-action="wardrobe-open">${n} ${n===1?'piece':'pieces'} inside</button></div><button class="open-hint" data-action="wardrobe-open">Tap the doors to open <span>↕</span></button></div>${syncNote()}${wearPrompt()}<button class="snapshot-link" data-action="go" data-value="wardrobe/snapshot"><span><strong>Your wardrobe snapshot</strong><small>Colours, balance, gaps and your recap</small></span><b>→</b></button><div class="wardrobe-dock two"><button class="wardrobe-add-btn" data-action="add-photos" aria-label="Add pieces">+</button><button class="wardrobe-primary" data-action="wardrobe-open">Open wardrobe</button></div></div>`;}
// Interior search matches name, brand, colour, type and category, so "blue kurta" or "Roadster" both work.
const matches=(p,q)=>!q||q.toLowerCase().split(/\s+/).filter(Boolean).every(w=>[p.name,p.brand,p.colour,p.type,p.category,p.retailer].join(' ').toLowerCase().includes(w));
function wardrobeOpen(){const live=state.items.filter(p=>category==='Archived'?p.archived:!p.archived),items=live.filter(p=>(category==='All'||category==='Archived'||p.category===category)&&matches(p,query)),hanging=items.filter(p=>['Shirts','Ethnic wear','Dresses','Suits','Outerwear'].includes(p.category)),folded=items.filter(p=>['Trousers','Footwear'].includes(p.category)),drawer=items.filter(p=>['Accessories','Belts','Jewellery'].includes(p.category));const counts=Object.fromEntries(CATEGORIES.map(c=>[c,state.items.filter(p=>p.category===c&&!p.archived).length]));const archived=state.items.filter(p=>p.archived).length;if(archived)counts.Archived=archived;const s=stats();const tile=(p,klass='')=>`<button class="${klass} ${p.art?'drawn':''}" data-action="wardrobe-look" data-id="${esc(p.id)}" aria-label="Open ${esc(p.name)}"><span class="hook"></span>${img(p)}<strong>${esc(p.name)}</strong></button>`;return `<div class="wardrobe-screen open-screen"><div class="wardrobe-head"><button data-action="wardrobe-close">← Close</button><button data-action="add-photos">+ Add pieces</button></div>${reviewBanner()}<label class="almirah-search"><span class="sr-only">Search your wardrobe</span><input id="wardrobe-search" type="search" placeholder="Search: blue kurta, Roadster, sneakers" value="${esc(query)}" maxlength="60" autocomplete="off"></label><div class="almirah-chips">${chip(`All ${state.items.length-archived}`,'almirah-category','All',category==='All')}${Object.entries(counts).filter(([,n])=>n).map(([c,n])=>chip(`${c} ${n}`,'almirah-category',c,category===c)).join('')}</div><div class="almirah interior">${hanging.length?`<section class="rail-section"><div class="wood-label"><strong>On the rail</strong><span>${hanging.length} hanging</span></div><div class="rail"></div><div class="hangers">${hanging.map(p=>tile(p,'hanger-item')).join('')}</div></section>`:''}${folded.length?`<section class="shelf-section"><div class="wood-label"><strong>Folded shelf</strong><span>${folded.length} folded</span></div><div class="folded-row">${folded.map(p=>tile(p,'folded-item')).join('')}</div></section>`:''}<section class="drawer-section"><div class="wood-label"><strong>Drawer · Belts & jewellery</strong></div><div class="drawer-face">${drawer.map(p=>tile(p,'drawer-item')).join('')||'<span class="drawer-empty">Room for the finishing touches</span>'}<small>Tap any piece to explode it</small></div></section>${!items.length?`<p class="almirah-none">Nothing matches “${esc(query)}”. <button class="link-btn" data-action="clear-search">Clear search</button></p>`:''}</div><div class="streak-dock"><div><strong>${s.streak?`Keep your ${s.streak}-day streak`:'Start a streak today'}</strong><small>Log what you wore today · +15 XP</small></div><button data-action="wear-today">Log wear</button></div></div>`;}
function wardrobeExploded(){const focused=route.split('/').pop(),chosen=item(focused)||state.items[0],ids=[chosen.id,...state.items.filter(p=>p.id!==chosen.id).slice(0,3).map(p=>p.id)],level=stats();return `<div class="wardrobe-screen exploded-screen"><div class="wardrobe-head"><button data-action="wardrobe-open-route">← Close</button><div class="assembly-toggle"><button class="${assemblyMode==='exploded'?'active':''}" data-action="assembly-mode" data-value="exploded">Exploded</button><button class="${assemblyMode==='stacked'?'active':''}" data-action="assembly-mode" data-value="stacked">Stacked</button></div></div><div class="wardrobe-title"><h1>${esc(chosen.name)} look</h1><p>${ids.length} pieces · all owned · Level ${level.number} ${level.title}</p></div><div class="assembly-panel ${assemblyMode}"><span class="assembly-axis"></span>${ids.map((id,i)=>{const p=item(id),wears=state.wears.filter(w=>w.items.includes(id)).length;return `<button class="assembly-piece ${id===focused?'focused':''}" style="--step:${i}" data-action="item" data-id="${id}">${img(p)}<span><strong>${esc(p.name)}</strong><small>Owned · worn ${wears}×${p.price&&wears?' · '+money(p.price/wears)+' / wear':''}</small></span></button>`;}).join('')}</div><div class="quick-actions"><button data-action="style-item" data-id="${focused}">Swap the ${esc(chosen.category.toLowerCase())}</button><button data-action="go" data-value="discover">Find similar</button><span>+15 XP</span></div><div class="wardrobe-dock two"><button class="wardrobe-save" data-action="log-ids" data-ids="${esc(ids.join(','))}">Log wear</button><button class="wardrobe-primary" data-action="style-item" data-id="${focused}">Style this look →</button></div></div>`;}
function wardrobe(){if(route.startsWith('wardrobe/item/'))return itemPage();if(route==='wardrobe/snapshot')return snapshot();if(route==='wardrobe/add'||(state.items.length<5&&route==='wardrobe'))return wardrobeAdd();if(route==='wardrobe/open')return wardrobeOpen();if(route.startsWith('wardrobe/look/'))return wardrobeExploded();return wardrobeClosed();}
function startDemoImport(){importDraft=[{...product('cream'),draftId:'d1',selected:true,warning:''},{...product('black'),id:'black-new',draftId:'d2',selected:false,warning:'Possible repeat of Black chinos. Compare before saving.',duplicate:'black'},{...product('belt'),id:'belt-new',draftId:'d3',selected:false,warning:'Possible repeat of Brown leather belt.',duplicate:'belt'},{id:'unclear',name:'Footwear — unclear',category:'Footwear',image:'assets/outfit.png',draftId:'d4',selected:false,warning:'Mostly out of frame. Replace the photo to add this piece.',unclear:true}];go('wardrobe/import');}
function jobStrip(){return jobs.length?`<div class="job-strip" role="status" aria-live="polite">${jobs.map(j=>`<div class="job ${j.done?'done':''} ${j.failed?'failed':''}"><span class="job-dot" aria-hidden="true"></span><span><strong>${esc(j.label)}</strong><small>${esc(j.text)}</small></span></div>`).join('')}</div>`:'';}
function importScreen(){const selected=importDraft.filter(p=>p.selected&&!p.unclear).length,hidden=importDraft.filter(p=>p.hidden),reasons=[...new Set(hidden.map(p=>p.hidden))].join(', ').toLowerCase(),shown=importDraft.filter(p=>(showHidden||!p.hidden)&&(importFilter==='All'||p.category===importFilter)),cutting=importDraft.filter(p=>p.cutting).length;return `<div class="toolbar"><button class="link-btn" data-action="go" data-value="wardrobe">${icon('back')} Back to wardrobe</button><button class="link-btn" data-action="add-photos">Add from another source</button></div>${heading('Make room for <em>your pieces.</em>','Check names, categories, and what belongs in your wardrobe.')}${jobStrip()}${notice(importDraft.some(p=>/order|screenshot/i.test(p.source||''))?'Order history import · check each piece before saving.':importDraft.some(p=>p.source)?'Pieces found for you · untick any that are not yours.':'Check each piece before saving.')}${cutting?`<p class="note cut-note">${cutting} ${cutting===1?'photo is':'photos are'} being cleaned up. You can keep reviewing.</p>`:''}${importDraft.length>6?draftFilters():''}${hidden.length?`<button class="hidden-toggle" data-action="toggle-hidden" aria-pressed="${showHidden}">${showHidden?'Hide':'Show'} ${hidden.length} hidden · ${esc(reasons)}</button>`:''}<div class="import-layout"><div class="stack">${shown.map(p=>`<article class="import-card ${p.selected?'selected':''} ${p.warning||p.hidden?'attention':''} ${p.cutting?'cutting':''}"><input type="checkbox" class="draft-check" aria-label="Select ${esc(p.name)}" data-draft="${p.draftId}" ${p.selected?'checked':''} ${p.unclear?'disabled':''}>${img(p,'thumb'+(p.cutout?' cutout':''))}<div class="import-fields"><label class="sr-only" for="name-${p.draftId}">Item name</label><input id="name-${p.draftId}" data-draft-name="${p.draftId}" value="${esc(p.name)}" maxlength="80" ${p.unclear?'disabled':''}><label class="sr-only" for="category-${p.draftId}">Category</label><select id="category-${p.draftId}" data-draft-category="${p.draftId}" ${p.unclear?'disabled':''}>${CATEGORIES.map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select>${p.cutting?'<span class="cut-badge">Cleaning up the photo…</span>':p.cutout?'<span class="cut-badge done">Background removed</span>':''}${p.hidden?`<p class="note warning">Hidden: ${esc(p.hidden.toLowerCase())}. Tick it if it is yours.</p>`:p.warning?`<p class="note warning">${esc(p.warning)}</p>`:(p.source?`<p class="note">${esc(p.description||p.source)}</p>`:'<p class="note">Brand not specified · you can rename this</p>')}${p.duplicate?`<button class="link-btn" data-action="compare-duplicate" data-id="${p.draftId}">Compare existing item</button>`:''}${p.unclear?'<button class="link-btn" data-action="upload-wardrobe">Use another photo</button>':''}</div></article>`).join('')||(jobs.some(j=>!j.done)?'<div class="empty"><h2>Finding your pieces…</h2><p>They appear here as soon as each one is found.</p></div>':'<div class="empty"><h2>Add your first photos</h2><p>Choose a small batch to get started.</p><button class="btn" data-action="add-photos">Choose a source</button></div>')}</div><aside class="panel import-summary"><div class="eyebrow">Your collection, coming together</div><h2><span id="selected-count">${selected}</span> <span id="selected-word">${selected===1?'piece':'pieces'}</span><br> ready to add.</h2><p class="note spaced">Only selected pieces will be saved. Uncertain items can wait until you have a better photo.</p><button class="btn full" id="save-import" data-action="save-import" ${selected?'':'disabled'}>Save ${selected} ${selected===1?'piece':'pieces'}</button><button class="link-btn" data-action="discard-import">Discard this import</button></aside></div>`;}
function board(ids,small=false){return `<div class="outfit-board ${small?'compact':''}">${ids.map((id,i)=>{const p=item(id);return p?`<div class="board-piece piece-${i}">${img(p)}<span>${esc(p.name)}</span></div>`:''}).join('')}</div>`;}
function style(){const owned=styleIds.filter(id=>state.items.some(p=>p.id===id)),missing=styleIds.filter(id=>!owned.includes(id));return `${heading(styleTitle.split(' · ').map((t,i)=>i?`<em>${esc(t)}</em>`:esc(t)).join(' · '),'Make a look. Then make it yours.',`<button class="link-btn" data-action="undo" ${previous?'':'disabled'}>${icon('undo')} Undo</button>`)}${notice('Outfit board · preset styling demonstration, not personal AI try-on.')}<div class="studio-layout"><div><div class="studio-preview"><span class="pill preview-badge">Outfit board</span>${board(styleIds)}<button class="compare-btn" data-action="compare" ${previous?'':'disabled'}>Compare looks</button></div><div class="row between spaced"><button class="link-btn" data-action="personal-photo">${icon('image')} Add my photo</button><button class="link-btn" data-action="save-look">${icon('bookmark')} Save look</button></div>${personalPhoto?`<div class="panel row"><img class="personal-thumb" src="${esc(personalPhoto)}" alt="Your original photo"><div><strong>Your original photo</strong><p class="note">Stored locally for this session. AI try-on is not connected.</p></div><button class="icon-btn" data-action="remove-personal" aria-label="Remove personal photo">${icon('close')}</button></div>`:''}</div><div class="stack"><div class="piece-tray">${styleIds.map(id=>{const p=item(id);return `<div class="tray-card ${kept.includes(id)?'kept':''}"><button class="tray-select" data-action="swap" data-id="${id}">${img(p)}<strong>${esc(p.name)}</strong></button><button class="keep-btn" data-action="keep" data-id="${id}" aria-pressed="${kept.includes(id)}">${kept.includes(id)?icon('lock'):icon('plus')} ${kept.includes(id)?'Kept':owned.includes(id)?'Owned · keep':'Addition · keep'}</button></div>`}).join('')}</div><div class="panel row between gap-summary"><div><strong>${owned.length} pieces owned · ${missing.length} ${missing.length===1?'addition':'additions'}</strong><p class="note">${missing.length?'Complete the look with '+missing.map(id=>item(id).name.toLowerCase()).join(', ')+'.':'Everything in this look is already in your wardrobe.'}</p></div>${missing.length?`<button class="btn" data-action="shop-look">Shop ${missing.length}</button>`:`<button class="btn" data-action="wear-look">Wore this</button>`}</div><div class="chip-row">${chip('Beach evening','occasion','Travel',styleOccasion==='Travel')}${chip('Formal setting','occasion','Work',styleOccasion==='Work')}${chip('Date night','occasion','Evening',styleOccasion==='Evening')}</div><div class="style-response"><span class="ribbon mini-ribbon" aria-hidden="true"></span><p>${esc(styleMessage)}</p></div><div class="chip-row">${chip('Swap trousers','swap-type','Trousers')}${chip('Add accessories','accessory','glasses')}${chip('Use only my wardrobe','owned-only','')}</div><form id="style-form" class="prompt-input"><input name="prompt" aria-label="Ask to style your outfit" placeholder="Keep the shirt, add accessories…" maxlength="250" required><button class="btn" type="submit" aria-label="Send styling request">${icon('arrow')}</button></form><p class="note">Try “formal”, “beach”, “white tee”, or “accessories” to explore preset responses.</p>${state.looks.length?`<button class="link-btn" data-action="saved-looks">${state.looks.length} saved ${state.looks.length===1?'look':'looks'} ${icon('arrow')}</button>`:''}</div></div>`;}
function itemStats(id){const p=item(id);const logs=state.wears.filter(w=>w.items.includes(id));return {p,logs,cpw:p?.price!=null&&logs.length?p.price/logs.length:null,variety:new Set(logs.map(w=>[...w.items].sort().join('|'))).size};}
function insights(){if(!state.items.length)return `${heading('Insights','Your wardrobe story starts with a piece.')}<div class="empty"><h2>A little more context, first.</h2><p>Add an item to see its usage, cost, and condition over time.</p><button class="btn" data-action="add-photos">Add your first piece</button></div>`;if(!state.items.some(p=>p.id===insightItem))insightItem=state.items[0].id;const s=itemStats(insightItem),{p,logs,cpw,variety}=s;const spend=state.items.reduce((a,p)=>a+(p.price||0),0),missing=state.items.filter(p=>p.price==null).length;const cards={cpw:['Cost per wear',cpw==null?'—':money(cpw),p.price==null?'Add a purchase price':`${money(p.price)} ÷ ${logs.length} recorded wears`],variety:['Outfit variety',variety,'Logged combinations, not suggestions'],spend:['Wardrobe spend',money(spend),`${state.items.length-missing} of ${state.items.length} prices recorded`],wears:['Recorded wears',logs.length,'For this item · all recorded history'],reviews:['Condition notes',p.reviews?.length||0,'Your observations over time']};const modeText=state.mode==='Frugal maxing'?`Your ${p.name.toLowerCase()} appears in ${variety} logged outfits.`:state.mode==='Splurge'?`What has your ${p.name.toLowerCase()} brought to your wardrobe?`:state.mode==='YOLO'?'Your style, on your terms.':`Your lens on ${p.name.toLowerCase()}.`;return `${heading('Insights','What your clothes do for you.',`<button class="icon-btn" data-action="custom-metrics" aria-label="Customize metrics">${icon('sliders')}</button>`)}${notice()}<div class="insight-controls"><div class="chip-row">${['Frugal maxing','Splurge','YOLO','Custom'].map(m=>chip(m,'mode',m,state.mode===m)).join('')}</div><label class="item-select">Explore item<select id="insight-item">${state.items.map(x=>`<option value="${x.id}" ${x.id===insightItem?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label></div><div class="insight-layout"><div class="stack"><div class="panel raised insight-story"><div class="eyebrow">${esc(state.mode)} / your perspective</div><h2>${esc(modeText)}</h2><p class="note spaced">${state.mode==='YOLO'?'Enjoyment and self-expression matter too. Social engagement is not connected in this preview.':'From your recorded history. Change the lens; keep the evidence.'}</p></div><div class="metric-grid">${state.metrics.filter(k=>cards[k]).map(k=>`<div class="panel metric-card"><span class="note">${cards[k][0]}</span><strong>${cards[k][1]}</strong><p class="note">${cards[k][2]}</p></div>`).join('')}</div><div class="panel"><div class="row between"><strong>Wears by occasion</strong><button class="link-btn" data-action="wear-history">View logs</button></div>${['Work','Evening','Travel','Casual','Untagged'].map(o=>{const n=logs.filter(w=>w.occasion===o).length;return n?`<div class="bar-row"><span>${o}</span><div class="bar-track"><div style="width:${logs.length?n/logs.length*100:0}%"></div></div><strong>${n}</strong></div>`:''}).join('')||'<p class="note spaced">No wears logged yet.</p>'}<p class="note spaced">${logs.filter(w=>w.occasion!=='Untagged').length} of ${logs.length} wears have an occasion tag.</p></div></div><aside class="stack"><div class="panel item-story">${img(p)}<div><h3>${esc(p.name)}</h3><p class="note">${p.purchased?'Owned since '+esc(p.purchased):'Purchase date not recorded'}</p></div>${(p.reviews||[]).slice(-1).map(r=>`<blockquote>“${esc(r.text)}”<cite>Your note · ${esc(r.date)}</cite></blockquote>`).join('')||'<p class="note">How is this piece holding up? Start its story.</p>'}<div class="row"><button class="link-btn" data-action="review" data-id="${p.id}">Add a review</button><button class="link-btn" data-action="style-item" data-id="${p.id}">Style it again ${icon('arrow')}</button></div></div><form class="panel stack" id="insight-form"><h3>Ask your wardrobe</h3><label class="sr-only" for="insight-query">Ask about this item</label><input id="insight-query" name="query" placeholder="Is this getting enough wear?" maxlength="250" required><button class="btn secondary" type="submit">Explore the numbers ${icon('arrow')}</button><span class="note">Uses recorded data and preset explanations.</span></form><p class="note warning">${missing?`${missing} ${missing===1?'piece has':'pieces have'} no purchase price. `:''}Wear logs may be incomplete. These are personal observations, not brand-wide quality ratings.</p></aside></div>`;}
function developer(){queueMicrotask(()=>window.DeveloperDashboard?.load());return window.DeveloperDashboard?.render()||'<div class="empty"><h2>Loading developer tools…</h2></div>';}
function render(){nav();const routes={discover:()=>(window.DiscoverConversation?.render()||discover())+(window.DiscoverHub?.render()||''), 'discover/select':selection,'discover/results':results,wardrobe,'wardrobe/add':wardrobe,'wardrobe/open':wardrobe,'wardrobe/import':importScreen,style:()=>window.Persona?.render()||style(),'style/outfits':style,profile:()=>`${window.Onboarding?.profileCard()||heading('My Profile')}${window.DiscoverConversation?.creditsCard?.()||''}`,insights:()=>heading('Insights','Coming soon. Your existing records are kept on this device.'),developer};if(/^wardrobe\/(look|item)\//.test(route))routes[route]=wardrobe;routes['wardrobe/snapshot']=wardrobe;if(!routes[route]){const overlay=/^(welcome|onboarding)$/.test(route);route='discover';if(!overlay)history.replaceState(null,'','#discover');nav();}const area=route.split('/')[0];main.innerHTML=`<section class="fade-in">${COMING_SOON.has(area)?comingSoon(area,routes[route]()):routes[route]()}</section>`;}
function updateImportCount(){const count=importDraft.filter(p=>p.selected&&!p.unclear).length;document.querySelector('#selected-count').textContent=count;const word=document.querySelector('#selected-word');if(word)word.textContent=count===1?'piece':'pieces';const b=document.querySelector('#save-import');b.textContent=`Save ${count} ${count===1?'piece':'pieces'}`;b.disabled=!count;}
function saveFind(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();toast(state.saved.includes(id)?'Saved to your inspiration.':'Removed from saved inspiration.');}
function productModal(id){const live=product(id);if(live?.live)return modal(esc(live.name),`<div class="item-detail">${img(live)}<div><p>${esc(live.retailer)}</p><p>${esc(live.priceText||'Check price at retailer')}</p><p class="note">${esc(live.description)}</p><a class="btn" href="${esc(live.url)}" target="_blank" rel="noopener noreferrer">Visit listing ↗</a></div></div>`,`<button class="btn secondary" data-action="save" data-id="${live.id}">Toggle saved inspiration</button>`);const p=item(id),owned=state.items.some(i=>i.id===id);modal(esc(p.name),`<div class="product-modal-layout">${img(p)}<div class="stack"><div><strong>${p.price==null?'Price not recorded':money(p.price)}</strong><p class="note">Illustrative item and price</p></div><p>${esc(p.description||'Added from your photo.')}</p><span class="pill ${owned?'green':'rose'}">${owned?'Owned':'Not owned'}</span><p class="note">Live merchant listings and stock are not connected. This panel previews the shopping handoff.</p></div></div>`,`<button class="btn" data-action="style-item" data-id="${id}">Style this piece</button>${owned?'':`<button class="btn secondary" data-action="confirm-own" data-id="${id}">I bought / own this</button><button class="link-btn" data-action="modal-save" data-id="${id}">${state.saved.includes(id)?'Unsave':'Save inspiration'}</button>`}`);}
function itemModal(id){const p=item(id);if(!state.items.some(i=>i.id===id))return productModal(id);if(state.v){close();return go('wardrobe/item/'+encodeURIComponent(id));}const s=itemStats(id);modal(esc(p.name),`<div class="item-detail">${img(p)}<div><span class="pill green">Owned</span><p class="note spaced">${esc(p.category)} · ${s.logs.length} recorded wears</p><p class="note">${p.price==null?'Price not recorded':money(p.price)+' purchase price'}</p><p class="note">${esc(p.source||'My Wardrobe')}</p></div></div>`,`<button class="btn" data-action="style-item" data-id="${id}">Style this</button><button class="btn secondary" data-action="edit-item" data-id="${id}">${icon('edit')} Edit</button><button class="link-btn" data-action="log-item" data-id="${id}">Log a wear</button><button class="link-btn" data-action="review" data-id="${id}">Condition review</button><button class="link-btn" data-action="item-insights" data-id="${id}">View insights</button>`);}
function remember(){previous={ids:[...styleIds],title:styleTitle,occasion:styleOccasion,message:styleMessage,kept:[...kept]};}
function styleItem(id){close();remember();const p=item(id);if(['Shirts','Trousers','Footwear'].includes(p.category))styleIds=styleIds.filter(x=>item(x)?.category!==p.category);if(!styleIds.includes(id))styleIds.unshift(id);styleIds=styleIds.slice(0,4);kept=kept.filter(x=>styleIds.includes(x));styleTitle=`Built around · ${p.name}`;styleMessage=`Start with ${p.name.toLowerCase()}. Keep the pieces you love and try a different pairing.`;go('style/outfits');}
function swapModal(id){const p=item(id);const choices=[...state.items,...catalog.filter(p=>!state.items.some(i=>i.id===p.id))].filter(x=>x.id!==id&&x.category===p.category);modal(`Swap ${esc(p.name)}`,kept.includes(id)?'<p>This piece is kept. Unkeep it first to try alternatives.</p>':`<div class="swap-grid">${choices.map(x=>`<button class="swap-option" data-action="swap-to" data-id="${x.id}" data-old="${id}">${img(x)}<strong>${esc(x.name)}</strong><span class="note">${state.items.some(i=>i.id===x.id)?'Owned':'Suggested addition'}</span></button>`).join('')||'<p>No other pieces in this category yet. Add a photo to grow your options.</p>'}</div>`);}
function addOwned(id){const p=product(id);if(state.items.some(i=>i.id===id)){toast('Already in your wardrobe.');close();return;}state.items.push({...p,owned:true,source:'Confirmed from Discover · sample item',purchased:new Date().toISOString().slice(0,10),reviews:[]});persist();close();render();toast('Added to My Wardrobe.');}
function addPhotos(){close();go('wardrobe/add');}
// Basics (PRD FR#8) are added straight away: the person chose each one, so there is nothing to review.
function addBasics(list){const W=window.WardrobeIntake,now=new Date().toISOString();for(const b of list)state.items.push({id:b.id,name:b.name,category:b.category,image:W.basicImage(b.shape,b.colour),art:{shape:b.shape,colour:b.colour},owned:true,source:'Basics',price:null,reviews:[],addedAt:now});persist();}
const todayIso=()=>new Date().toISOString().slice(0,10);
const ago=d=>{if(!d)return '—';const n=Math.round((new Date(todayIso())-new Date(d))/864e5);return n<=0?'Today':n===1?'Yesterday':n<30?`${n} days ago`:n<365?`${Math.round(n/30)} mo ago`:`${Math.round(n/365)} yr ago`;};
// A quick daily "What did you wear?" (PRD FR#14), only until today's wear is logged.
function wearPrompt(){if(!state.items.length||state.wears.some(w=>w.date===todayIso()))return '';return `<button class="wear-prompt" data-action="wear-today"><span><strong>What did you wear today?</strong><small>Tick the pieces · +15 XP and your streak</small></span><b>Log it</b></button>`;}
function wearIds(ids){const owned=ids.filter(id=>state.items.some(p=>p.id===id));if(!owned.length)return;const t=todayIso();const same=state.wears.find(w=>w.date===t&&w.items.join(',')===owned.join(','));if(same)return toast('Already logged for today.');state.wears.push({id:crypto.randomUUID(),date:t,occasion:'Untagged',items:owned});persist();render();const st=stats();toast(`Wear logged · +15 XP${st.streak>1?` · ${st.streak}-day streak`:''}`);}
// The item page (PRD FR#13): big picture, every detail editable in place, wears and cost per wear,
// the looks it is in, and "complete this look" from the person's own wardrobe first.
function itemPage(){const id=decodeURIComponent(route.slice('wardrobe/item/'.length)),p=state.items.find(i=>i.id===id);if(!p)return `<div class="empty"><h2>This piece is not in your wardrobe.</h2><button class="btn" data-action="go" data-value="wardrobe/open">Back to your wardrobe</button></div>`;
 const s=itemStats(id),last=s.logs.map(w=>w.date).sort().pop(),c=window.WardrobeInsights?.complete(p,state)||{picks:[],missing:[]},looks=state.looks.filter(l=>l.ids.includes(id)),wornToday=s.logs.some(w=>w.date===todayIso()),lookIds=[id,...c.picks.map(x=>x.id)];
 const field=(name,label,value,extra='')=>`<label class="field">${label}<input name="${name}" value="${esc(value??'')}" ${extra}></label>`;
 const tile=x=>`<button class="look-piece ${x.art?'drawn':''}" data-action="go" data-value="wardrobe/item/${esc(encodeURIComponent(x.id))}">${img(x,x.cutout?'cutout':'')}<span>${esc(x.name)}</span></button>`;
 return `<div class="wardrobe-screen item-page"><div class="wardrobe-head"><button data-action="wardrobe-open-route">← Wardrobe</button>${p.archived?'<span class="pill">Archived</span>':p.status&&p.status!=='available'?`<span class="pill">${esc({laundry:'In the laundry',lent:'Lent out',tailor:'At the tailor',stored:'Stored away'}[p.status])}</span>`:''}</div>
<div class="item-hero ${p.art?'drawn':''}">${img(p,p.cutout?'cutout':'')}</div>
<div class="item-stats"><div><strong>${s.logs.length}</strong><span>${s.logs.length===1?'wear':'wears'}</span></div><div><strong>${ago(last)}</strong><span>last worn</span></div><div><strong>${s.cpw==null?'—':money(s.cpw)}</strong><span>${p.price==null?'add a price to see cost per wear':'per wear'}</span></div></div>
<button class="wardrobe-primary full" data-action="worn-today" data-id="${esc(id)}" ${wornToday?'disabled':''}>${wornToday?'Worn today ✓':'Mark as worn today · +15 XP'}</button>
<section class="complete-look"><div class="wood-label"><strong>Complete this look</strong><span>From your wardrobe first</span></div><div class="look-row">${[p,...c.picks].map(tile).join('')}</div>${c.missing.length?`<div class="gap-row">${c.missing.map(m=>`<button class="gap-chip" data-action="discover-search" data-value="${esc(lookSearch(p,m))}">No ${esc(m.toLowerCase())} for this · find on Discover →</button>`).join('')}</div>`:''}${c.picks.length?`<div class="row"><button class="link-btn" data-action="log-today" data-ids="${esc(lookIds.join(','))}">Wore this look today</button><button class="link-btn" data-action="save-closet-look" data-ids="${esc(lookIds.join(','))}">Save this look</button></div>`:''}</section>
${looks.length?`<section class="item-looks"><h2>In your saved looks</h2>${looks.map(l=>`<div class="saved-look-row"><span>${esc(l.title)}<small>${l.ids.length} pieces</small></span><button class="link-btn" data-action="log-today" data-ids="${esc(l.ids.join(','))}">Wore it today</button></div>`).join('')}</section>`:''}
<form id="item-form" data-id="${esc(id)}" class="item-fields stack"><h2>Details</h2>${field('name','Name',p.name,'required maxlength="80"')}<label class="field">Category<select name="category">${CATEGORIES.map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label><div class="form-columns">${field('brand','Brand',p.brand,'maxlength="60"')}${field('colour','Colour',p.colour||p.color,'maxlength="30"')}</div><div class="form-columns">${field('size','Size',p.size,'maxlength="20"')}${field('price','Price (₹)',p.price,'type="number" min="0" max="10000000" step="1" placeholder="Optional"')}</div><div class="form-columns"><label class="field">Bought on<input name="purchased" type="date" max="${todayIso()}" value="${esc(p.purchased||'')}"></label><label class="field">Where it is<select name="status">${[['available','In my wardrobe'],['laundry','In the laundry'],['lent','Lent out'],['tailor','At the tailor'],['stored','Stored away']].map(([v,l])=>`<option value="${v}" ${(p.status||'available')===v?'selected':''}>${l}</option>`).join('')}</select></label></div><button class="btn secondary" type="submit">Save details</button></form>
${p.productUrl?`<a class="link-btn store-link" href="${esc(p.productUrl)}" target="_blank" rel="noopener">Open on ${esc(p.retailer||'the store')} ${icon('arrow')}</a>`:''}
<div class="item-actions">${COMING_SOON.has('style')?'':`<button data-action="style-item" data-id="${esc(id)}">Style this item</button>`}<button data-action="duplicate-item" data-id="${esc(id)}">Same piece, another colour</button><button data-action="review" data-id="${esc(id)}">Condition note</button><button data-action="archive-item" data-id="${esc(id)}">${p.archived?'Bring back':'Archive'}</button><button class="danger" data-action="remove-item" data-id="${esc(id)}">Remove</button></div></div>`;}
const lookSearch=(p,category)=>({Trousers:'trousers',Footwear:'shoes',Shirts:'shirt','Ethnic wear':'kurta',Outerwear:'jacket',Accessories:'accessories',Belts:'belt',Jewellery:'jewellery'}[category]||category.toLowerCase())+` to wear with a ${[p.colour||p.color,p.type||p.category].filter(Boolean).join(' ').toLowerCase()}`;
// The snapshot (PRD FR#15): never empty from the first piece. Gaps unlock at 20 pieces (FR#16).
function snapshot(){const I=window.WardrobeInsights;const live=state.items.filter(p=>!p.archived);if(!I||!live.length)return `<div class="wardrobe-screen">${heading('Your snapshot','Add a piece to start it.')}<button class="btn" data-action="add-photos">Add pieces</button></div>`;
 const pal=I.palette(live),bal=I.balance(live,CATEGORIES),gap=I.gaps(live,window.TBWAccount?.profile),season=seasonRange(),r=I.recap(state,season),left=Math.max(0,20-live.length);
 return `<div class="wardrobe-screen snapshot"><div class="wardrobe-head"><button data-action="go" data-value="wardrobe">← Wardrobe</button></div><div class="wardrobe-title"><h1>Your snapshot</h1><p>${live.length} ${live.length===1?'piece':'pieces'} · ${state.wears.length} ${state.wears.length===1?'wear':'wears'} logged</p></div>
<section class="snap-card"><h2>Your colours</h2>${pal.length?`<div class="palette">${pal.map(c=>`<span class="swatch"><i style="background:${esc(c.hex)}"></i>${esc(c.name)} <b>${c.count}</b></span>`).join('')}</div>`:'<p class="note">Colours show up as pieces are read from photos and orders.</p>'}</section>
<section class="snap-card"><h2>What it is made of</h2>${bal.map(b=>`<div class="bar-row"><span>${esc(b.category)}</span><div class="bar-track"><div style="width:${Math.round(b.share*100)}%"></div></div><strong>${b.count}</strong></div>`).join('')}</section>
<section class="snap-card"><h2>Gaps</h2>${left?`<p class="note">Add ${left} more ${left===1?'piece':'pieces'} and we will show what your wardrobe is missing for weddings, work and winter.</p><div class="unlock-track"><i style="width:${(live.length/20)*100}%"></i></div>`:gap.length?gap.map(g=>`<button class="gap-card" data-action="discover-search" data-value="${esc(g.search)}"><span><strong>${esc(g.title)}</strong><small>${esc(g.why)}</small></span><b>Find one →</b></button>`).join(''):'<p class="note">Nothing obvious is missing. Nicely done.</p>'}</section>
<section class="snap-card recap" id="recap"><div class="eyebrow">${esc(season.label)} recap</div>${r.wears?`<h2>${r.days} ${r.days===1?'day':'days'} dressed, ${r.wears} ${r.wears===1?'outfit':'outfits'} logged</h2><ul class="recap-list">${r.mostWorn[0]?`<li><span>Most worn</span><strong>${esc(r.mostWorn[0].item.name)} · ${r.mostWorn[0].wears}×</strong></li>`:''}<li><span>Never worn yet</span><strong>${r.neverWorn.length} ${r.neverWorn.length===1?'piece':'pieces'}</strong></li>${r.colours.length?`<li><span>Your colours</span><strong>${r.colours.map(c=>esc(c.name)).join(', ')}</strong></li>`:''}${r.bestValue?`<li><span>Best value</span><strong>${esc(r.bestValue.item.name)} · ${money(r.bestValue.cpw)} a wear</strong></li>`:''}</ul><button class="btn secondary" data-action="share-recap">Share my recap</button>`:`<h2>Your recap fills in as you log what you wear.</h2><button class="btn secondary" data-action="wear-today">Log today's outfit</button>`}</section></div>`;}
function seasonRange(d=new Date()){const y=d.getFullYear(),m=d.getMonth();const [label,from,to]=m<2||m===11?['Winter',m===11?`${y}-12-01`:`${y-1}-12-01`,m===11?`${y+1}-02-31`:`${y}-02-31`]:m<5?['Summer',`${y}-03-01`,`${y}-05-31`]:m<9?['Monsoon',`${y}-06-01`,`${y}-09-30`]:['Festive season',`${y}-10-01`,`${y}-11-30`];return {label,from,to};}
function recapText(){const I=window.WardrobeInsights,season=seasonRange(),r=I.recap(state,season);return [`My ${season.label.toLowerCase()} on The Wardrobe OS:`,`${r.days} days dressed, ${r.wears} outfits logged`,r.mostWorn[0]&&`Most worn: ${r.mostWorn[0].item.name} (${r.mostWorn[0].wears}×)`,r.colours.length&&`My colours: ${r.colours.map(c=>c.name).join(', ')}`,r.bestValue&&`Best value: ${r.bestValue.item.name} at ${money(r.bestValue.cpw)} a wear`].filter(Boolean).join('\n');}
function wearPicker(){if(!state.items.length)return toast('Add a piece before logging a wear.');modal('What did you wear today?',`<form id="wear-pick-form" class="stack"><div class="wear-picks">${state.items.map(p=>`<label class="wear-pick"><input type="checkbox" name="piece" value="${esc(p.id)}">${img(p,'thumb')}<span>${esc(p.name)}</span></label>`).join('')}</div><label class="field">Occasion<select name="occasion">${['Work','Evening','Travel','Casual','Untagged'].map(o=>`<option>${o}</option>`).join('')}</select></label><button class="btn" type="submit">Log today's wear · +15 XP</button></form>`);}
// "Paste a product link": the server reads the store's own product page (name, brand, photo, price).
async function readLink(url){const job=newJob('Reading your link');close();go('wardrobe/import');soft();try{const r=await fetch('/api/wardrobe/link',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'That link could not be read.');const p=d.product,host=new URL(p.productUrl||url).hostname.replace(/^www\./,''),found=window.OrderImport?.classify?.(p.name)||'unknown',known=CATEGORIES.includes(found);addDraft([{id:'link-'+host.split('.')[0]+'-'+[...(p.productUrl||url)].reduce((h,c)=>(h*31+c.charCodeAt(0))>>>0,7).toString(36),name:p.name,brand:p.brand,price:p.price,image:p.image,productUrl:p.productUrl,retailer:host,category:known?found:'Accessories',selected:known,warning:known?'':'Category unclear · check before saving.'}],host,'Product link');endJob(job,`Found ${p.name}`);}catch(e){endJob(job,e.message||'That link could not be read.',true);}}
// Import channels, strongest first: shopping apps (connectors ship with the native app; Amazon
// works now via its export), order screenshots, Instagram, Google Photos, then the camera.
let emailReady=false,inboxPulled=0,connectorsEnabled=false,googlePhotosReady=false,importFilter='All',jobs=[],showHidden=false,cutoutsReady=null,softTimer=null,aiResolve=null;
// Default order follows the owner's priority (14 Oct 2026); "Where do you shop?" picks go first.
const STORES=[['myntra','Myntra'],['flipkart','Flipkart'],['amazon','Amazon'],['ajio','AJIO'],['nykaafashion','Nykaa Fashion'],['meesho','Meesho'],['slikk','Slikk'],['tatacliq','Tata CLiQ']];
const CONNECTED=new Set(['myntra','flipkart','slikk','ajio','tatacliq','nykaafashion']);
const orderedStores=()=>[...STORES].sort((a,b)=>{const i=x=>{const n=(state.shops||[]).indexOf(x[0]);return n<0?99:n;};return i(a)-i(b);});
// In the phone app a store opens in an in-app browser; on the web, Amazon has its order file and the rest point to screenshots.
// Each store's last import (PRD FR#5), and the next store to try.
function noteSync(id,count){state.syncs??={};state.syncs[id]={at:new Date().toISOString(),count};persist();}
const nextStore=()=>orderedStores().find(([id])=>!state.syncs?.[id]&&storeAction(id)!=='store-connect')?.[1]||'';
function storeStatus(){const rows=orderedStores().filter(([id])=>state.syncs?.[id]);return rows.length?`<div class="store-syncs">${rows.map(([id,label])=>`<div class="store-sync"><span><strong>${esc(label)}</strong><small>${state.syncs[id].count} ${state.syncs[id].count===1?'piece':'pieces'} found · ${esc(ago(state.syncs[id].at.slice(0,10)).toLowerCase())}</small></span><button class="link-btn" data-action="${storeAction(id)}" data-id="${id}" data-value="${esc(label)}">Import again</button></div>`).join('')}</div>`:'';}
function storeAction(id){if(window.NativeImport?.available(id))return 'store-native';if(id==='amazon')return 'amazon-import';if(connectorsEnabled&&CONNECTED.has(id))return 'store-pull';return 'store-connect';}
function importHub(){const stores=orderedStores();return `<div class="wardrobe-label">Import your wardrobe</div><div class="source-list"><div class="store-card"><div class="store-card-head"><span><strong>From your shopping apps</strong><small>Bring in past orders with real product photos</small></span><button class="link-btn" data-action="shops">${state.shops?.length?'Edit my stores':'Where do you shop?'}</button></div><div class="store-row">${stores.map(([id,label])=>{const action=storeAction(id);return `<button class="store-chip ${action==='store-connect'?'':'ready'} ${state.shops?.includes(id)?'mine':''}" data-action="${action}" data-id="${id}" data-value="${label}">${label}${action==='amazon-import'?' · order file':''}</button>`;}).join('')}</div>${storeStatus()}</div><button class="recommended" data-action="import-screenshots"><i class="source-icon"></i><span><em>Works with any shopping app</em><strong>Import order screenshots</strong><small>Screenshot your order history. We pick out each piece and its photo</small></span><b>→</b></button><button data-action="import-camera"><i class="source-icon"></i><span><strong>Snap your clothes</strong><small>Several pieces or a whole outfit per photo · up to 10 photos at once</small></span><b>→</b></button><button data-action="basics"><i class="source-icon"></i><span><strong>Add your basics</strong><small>White tee, blue jeans, kurtas, sneakers · one tap each</small></span><b>→</b></button><button data-action="link-paste"><i class="source-icon"></i><span><strong>Paste a product link</strong><small>From Myntra, AJIO, Amazon and more</small></span><b>→</b></button>${emailReady?`<button data-action="email-forward"><i class="source-icon"></i><span><strong>Forward order emails</strong><small>Zara, H&amp;M, Uniqlo, any brand · we read only what you forward</small></span><b>→</b></button>`:''}<button data-action="import-instagram"><i class="source-icon"></i><span><strong>Instagram</strong><small>Find the clothes in your posts</small></span><b>→</b></button>${googlePhotosReady?`<button data-action="import-google"><i class="source-icon"></i><span><strong>Google Photos</strong><small>Pick up to 20 outfit photos</small></span><b>→</b></button>`:''}</div><p class="wardrobe-note">We only read what you choose, and nothing is saved until you review it. <button class="link-btn" data-action="upload-wardrobe">Add photos and name them myself</button></p>`;}
// Long imports (a Myntra history is 70+ cards) need filtering and bulk ticking on a phone.
function draftFilters(){const counts={};for(const p of importDraft)counts[p.category]=(counts[p.category]||0)+1;const chip=(value,label,n)=>`<button class="draft-chip ${importFilter===value?'active':''}" data-action="draft-filter" data-value="${esc(value)}" aria-pressed="${importFilter===value}">${esc(label)} ${n}</button>`;return `<div class="draft-tools"><div class="draft-filters" role="group" aria-label="Filter by category">${chip('All','All',importDraft.length)}${CATEGORIES.filter(c=>counts[c]).map(c=>chip(c,c,counts[c])).join('')}</div><div class="draft-select"><button class="link-btn" data-action="draft-select" data-value="all">Select all${importFilter==='All'?'':' '+esc(importFilter.toLowerCase())}</button><button class="link-btn" data-action="draft-select" data-value="none">Select none</button></div></div>`;}
function pickFiles({accept,multiple=true,capture}={}){return new Promise(resolve=>{const input=document.createElement('input');input.type='file';input.accept=accept;input.multiple=multiple;if(capture)input.setAttribute('capture',capture);input.onchange=()=>resolve(input.files);input.click();});}
// Re-renders while imports stream in without stealing focus from the field being edited.
function soft(){if(softTimer)return;softTimer=setTimeout(()=>{softTimer=null;if(!route.startsWith('wardrobe')){nav();return;}const a=document.activeElement,id=a?.id,pos=a?.selectionStart,y=window.scrollY;render();if(id){const f=document.querySelector('#'+id);if(f){f.focus({preventScroll:true});if(pos!=null)try{f.setSelectionRange(pos,pos);}catch{}}}window.scrollTo(0,y);},60);}
// Photos go to our AI providers to be read and cleaned up; say so once, before the first one (PRD NFR#3).
function aiOk(){if(state.aiConsent)return Promise.resolve(true);return new Promise(resolve=>{aiResolve=resolve;modal('Your photos, read by AI',`<p>To find each piece, the photos and screenshots you choose are sent to our AI providers (Google Gemini, with OpenAI as a backup) to read them and remove the background.</p><p class="note spaced">Only the photos you pick are sent. Nothing is added to your wardrobe until you review and save it.</p>`,`<button class="btn" data-action="ai-yes">Continue</button><button class="btn secondary" data-action="ai-no">Not now</button>`);});}
function newJob(label){const job={id:crypto.randomUUID(),label,text:'Getting started…',done:false};jobs.push(job);return job;}
function endJob(job,text,failed=false){job.done=true;job.failed=failed;job.text=text;soft();setTimeout(()=>{jobs=jobs.filter(j=>j!==job);soft();},failed?12000:6000);}
// Imports run in the background and stream into the review queue (PRD FR#2, FR#9): no blocking spinner.
async function runImport(title,task,label,source){if(!await aiOk())return;close();const job=newJob(title);go('wardrobe/import');soft();try{const r=await task(t=>{job.text=t;soft();},items=>{addDraft(items,label,source);soft();});const fresh=addDraft(r.items||[],label,source);const total=importDraft.filter(p=>p.source===source).length;endJob(job,summary(r,total||fresh.length));}catch(e){endJob(job,e.message||'That import did not work. Try again.',true);}}
function summary({skipped=0,empty=0,manual=0,failed=0}={},found=0){return [`${found} ${found===1?'piece':'pieces'} found`,skipped&&`${skipped} returned or not clothing`,empty&&`${empty} ${empty===1?'photo':'photos'} without clear clothes`,manual&&`${manual} to name by hand`,failed&&`${failed} could not be read, try again`].filter(Boolean).join(' · ');}
// Adds candidates to the review queue: duplicates flagged, innerwear, kids' sizes and likely gifts
// hidden (PRD FR#4), photo crops queued for a background cleanup (PRD FR#10).
function addDraft(items,label,source){const owned=new Set(state.items.map(i=>i.id)),profile=window.TBWAccount?.profile,screen=window.WardrobeIntake?.screen||(()=>'');const same=window.WardrobeInsights?.similar||((a,b)=>a.id===b.id);const fresh=items.filter(p=>!importDraft.some(d=>d.id===p.id||same(d,p))).map(p=>{const twin=owned.has(p.id)?p.id:state.items.find(i=>same(i,p))?.id,dup=Boolean(twin),hidden=dup?'':screen(p,profile);return {...p,draftId:'draft-'+crypto.randomUUID(),image:p.image||NO_PHOTO,description:[p.brand,p.size&&'Size '+p.size,p.orderedAt&&'Ordered '+p.orderedAt,p.price&&'₹'+Number(p.price).toLocaleString('en-IN')+(p.priceFromScreenshot?' (check the price)':'')].filter(Boolean).join(' · ')||source,tags:[p.brand,p.type].filter(Boolean),retailer:p.retailer||label,source,purchased:p.orderedAt||undefined,duplicate:twin,hidden,selected:p.selected&&!dup&&!hidden,warning:dup?'Already in your wardrobe.':p.warning};});importDraft.push(...fresh);queueCutouts(fresh);return fresh;}
function draftPieces(items,label,source,stats={}){close();if(!items.length){toast(stats.empty?`No clothes found in those photos. Try photos where your outfit is clearly visible.`:`No clothing found from ${label}.`);return;}const fresh=addDraft(items,label,source);importFilter='All';go('wardrobe/import');render();toast(summary(stats,fresh.length)+'.');}
// Background cleanup: three at a time; the original crop stays if a cutout fails.
const cutQueue=[];let cutActive=0;
function queueCutouts(list){if(cutoutsReady===false||typeof fetch!=='function')return;for(const p of list)if(p.needsCutout&&!p.cutout&&!p.cutting){p.cutting=true;cutQueue.push(p);}pumpCuts();}
function pumpCuts(){while(cutActive<3&&cutQueue.length){const p=cutQueue.shift();if(!importDraft.includes(p)&&!p.savedAs){p.cutting=false;continue;}cutActive++;fetch('/api/wardrobe/cutout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({image:p.image,label:[p.colour,p.type||p.category].filter(Boolean).join(' ').toLowerCase()})}).then(async r=>{const d=await r.json().catch(()=>({}));if(r.ok&&d.image){p.image=d.image;p.cutout=true;const saved=p.savedAs&&state.items.find(i=>i.id===p.savedAs);if(saved){saved.image=d.image;saved.cutout=true;persist();}}else if(r.status===429||r.status===503){for(const q of cutQueue)q.cutting=false;cutQueue.length=0;}}).catch(()=>{}).finally(()=>{p.cutting=false;cutActive--;soft();pumpCuts();});}}
let instagramPhotos=[],tapQueue=null,lastPointer=null;
// Group photos hold other people's clothes, so each chosen photo asks "which one is you?" before detection.
function startTap(images,label,source){tapQueue={images,label,source,i:0,done:[],point:null};showTap();}
function showTap(){const q=tapQueue,src=q.images[q.i];q.point=null;modal(`Which one is you? <span class="note">${q.i+1} of ${q.images.length}</span>`,`<p class="step-tag">Step 3 of 3 · find you</p><p class="note">Tap yourself so we only add your outfit, not your friends'.</p><div class="tap-stage"><button type="button" class="tap-photo" data-action="tap-point" aria-label="Photo ${q.i+1}: tap where you are"><img src="${esc(src)}" alt=""><i class="tap-dot" hidden></i></button></div>`,`<button class="btn" id="tap-use" data-action="tap-next" disabled>That's me</button><button class="btn secondary" data-action="tap-solo">Only I'm in this photo</button><button class="link-btn" data-action="tap-skip">I'm not in this photo</button>`);}
function tapAdvance(entry){const q=tapQueue;if(entry)q.done.push(entry);q.i++;if(q.i<q.images.length)return showTap();tapQueue=null;if(!q.done.length){close();return toast('No photos chosen. Pick photos you are in.');}runImport('Finding your clothes',(u,add)=>window.Importers.pieces(q.done,u,add),q.label,q.source);}

// Order exports carry no photos (Amazon) or remote ones (Myntra/Flipkart); a labelled placeholder beats a guessed image.
const NO_PHOTO='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 400"><rect width="300" height="400" fill="#f1ede6"/><text x="150" y="205" text-anchor="middle" font-family="Montserrat,sans-serif" font-size="18" fill="#8a8178">Photo needed</text></svg>');
function chooseFiles(purpose){uploadPurpose=purpose;fileInput.multiple=purpose==='wardrobe';fileInput.value='';fileInput.click();}
async function filesChosen(files){const valid=[...files].filter(f=>['image/jpeg','image/png','image/webp'].includes(f.type)&&f.size<=10*1024*1024);if(!valid.length){toast('Choose a JPG, PNG or WebP image smaller than 10 MB.');return;}if(valid.length<files.length)toast('Some files were skipped. Use JPG, PNG or WebP under 10 MB.');if(valid.length>5)toast('Using the first five photos.');const data=await Promise.all(valid.slice(0,uploadPurpose==='wardrobe'?5:1).map(f=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>{const check=new Image();check.onload=()=>resolve({url:r.result,name:f.name});check.onerror=()=>reject(new Error('Unreadable image'));check.src=r.result;};r.onerror=reject;r.readAsDataURL(f);})));close();if(uploadPurpose==='discover'){ref={image:data[0].url,label:data[0].name,sample:false};go('discover/select');}else if(uploadPurpose==='personal'){personalPhoto=data[0].url;go('style/outfits');render();}else{importDraft.push(...data.map((d,i)=>({id:'upload-'+crypto.randomUUID(),draftId:'draft-'+crypto.randomUUID(),name:d.name.replace(/\.[^.]+$/,''),category:'Shirts',image:d.url,price:null,selected:true,uploaded:true})));go('wardrobe/import');render();}}
function editItem(id){const p=item(id);modal('Edit your piece',`<form id="edit-form" data-id="${id}" class="stack"><label class="field">Name<input name="name" value="${esc(p.name)}" required maxlength="80"></label><label class="field">Category<select name="category">${CATEGORIES.map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label><div class="form-columns"><label class="field">Purchase price (₹)<input name="price" type="number" min="0" max="10000000" step="1" value="${p.price??''}" placeholder="Optional"></label><label class="field">Purchase date<input name="purchased" type="date" max="${new Date().toISOString().slice(0,10)}" value="${esc(p.purchased||'')}"></label></div><button class="btn" type="submit">Save changes</button></form><button class="link-btn danger spaced" data-action="remove-item" data-id="${id}">Remove from wardrobe</button>`);}
function reviewModal(id){const p=item(id);modal('How is it holding up?',`<p class="note">${esc(p.name)} · your personal item history</p><div class="review-history">${(p.reviews||[]).map(r=>`<blockquote>“${esc(r.text)}”<cite>${esc(r.date)} · ${r.rating}/5 condition</cite></blockquote>`).join('')}</div><form id="review-form" data-id="${id}" class="stack"><label class="field">Condition<select name="rating"><option value="5">5 — Like new</option><option value="4">4 — Holding up well</option><option value="3">3 — Some wear</option><option value="2">2 — Needs a repair</option><option value="1">1 — No longer wearable</option></select></label><label class="field">Your note<textarea name="text" placeholder="How are the fabric, stitching, buttons or shape holding up?" required maxlength="600" rows="4"></textarea></label><button class="btn" type="submit">Save condition note</button></form>`);}
function logWear(ids){const owned=ids.filter(id=>state.items.some(p=>p.id===id));if(!owned.length)return toast('Add an owned piece before logging a wear.');modal('Log a wear',`<p class="note">${owned.map(id=>esc(item(id).name)).join(', ')}</p><form class="stack spaced" id="wear-form" data-ids="${owned.join(',')}"><label class="field">When?<input name="date" type="date" value="${new Date().toISOString().slice(0,10)}" max="${new Date().toISOString().slice(0,10)}" required></label><label class="field">Occasion<select name="occasion">${['Work','Evening','Travel','Casual','Untagged'].map(o=>`<option ${o===styleOccasion?'selected':''}>${o}</option>`).join('')}</select></label><button class="btn" type="submit">Confirm I wore this</button><span class="note">Only owned pieces are recorded. This updates your local Insights.</span></form>`);}
function customMetrics(){modal('Your metrics, your lens.',`<form id="metrics-form" class="stack"><p class="note">Choose the numbers you want to see.</p>${[['cpw','Cost per wear'],['variety','Outfit variety'],['spend','Recorded wardrobe spend'],['wears','Recorded wears'],['reviews','Condition notes']].map(([k,n])=>`<label class="check-row"><input type="checkbox" name="metric" value="${k}" ${state.metrics.includes(k)?'checked':''}>${n}</label>`).join('')}<button class="btn" type="submit">Apply my lens</button></form>`);}
function about(){modal('Your Atelier walkthrough',`<p>This is a local, interactive design prototype based on your seven Atelier screens.</p><ol class="walkthrough"><li>Discover → try an example → choose a target → inspect and save a sample match.</li><li>My Wardrobe → Add photos → try the sample import or upload your own → review and save.</li><li>Style Me → keep and swap pieces → save a look → confirm a purchase or log a wear.</li><li>Insights → choose a lens → review a piece → see its recorded history.</li></ol><p class="note">Changes are saved in this browser. Discover supports live search when provider keys are configured. Wardrobe extraction, personal AI try-on, social connections, and checkout remain demonstrations. Example product imagery and prices are illustrative.</p>`,`<button class="btn" data-action="close">Let's explore</button><button class="btn secondary" data-action="reset-confirm">Reset sample data</button>`);}
